D[2660]={"^|cFF66DDFFLevel 10 Passive|r\nDirect damage dealt now has a (.-)%% chance to reset the cooldown of |cffffffffSerpent's Fang|r and grant you |cffffffffRot Lich|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nSeu dano direto agora tem {{1}}% de chance de reiniciar a recarga de |cffffffffPresa da Serpente|r e conceder |cffffffffLich Pútrido|r."}
D[2661]={"^|cFF66DDFFLevel 10 Passive|r\nYour |cffffffffVenom Fang|r now applies a |cff66ff66Brood Mark|r for (.-), stacking (.-) times%. Some abilities will consume them for an additional effect%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nSua |cffffffffPresa Venenosa|r agora aplica uma |cff66ff66Marca da Prole|r durante {{1}}, acumulando até {{2}} vezes. Algumas habilidades consomem essas marcas para gerar um efeito adicional."}
D[3685]={"^Increases the bonus healing scaling of |cffffffffSerpent's Fang|r, |cffffffffMending Mist|r, and |cffffffffShadra's Balm|r by (.-)%%%.%s*$","Aumenta a escalabilidade do bônus de cura de |cffffffffPresa da Serpente|r, |cffffffffManto de brumas curativa|r e |cffffffffBálsamo de Shadra|r em {{1}}%."}
D[3783]={"^Spray poison on an enemy and all enemies near them, dealing (.-) Nature damage and reducing their attack speed by (.-)%% for (.-)%.%s*$","Borrifa veneno sobre um inimigo e todos os inimigos próximos, causando {{1}} de dano de Natureza e reduzindo a velocidade de ataque deles em {{2}}% durante {{3}}."}
D[3791]={"^Place a toxic pool on the ground for (.-), instantly |cffff4500Burning|r enemies inside for (.-) Nature Damage%.\n\nEnemies in the pool take (.-) Nature Damage every (.-) sec, and have (.-)%% reduced movement speed%.\n\nAllies in the pool are healed for (.-) every (.-) sec and take (.-)%% increased healing%.%s*$","Coloca uma poça tóxica no chão durante {{1}}, causando dano |cffff4500Ardente|r os inimigos dentro em {{2}} de dano de Natureza instantaneamente.\n\nOs inimigos na poça sofrem {{3}} de dano de Natureza a cada {{4}} s, e têm uma redução do {{5}}% em velocidade de movimento.\n\nOs aliados na poça recebem cura em {{6}} a cada {{7}} s e sofrem um aumento do {{8}}% na cura."}
D[3792]={"^Place a toxic pool on the ground for (.-), instantly |cffff4500Burning|r enemies inside for (.-) Nature Damage%.\n\nEnemies in the pool take (.-) Nature Damage every (.-) sec, and have (.-)%% reduced movement speed%.%s*$","Coloca uma poça tóxica no chão durante {{1}}, causando dano |cffff4500Ardente|r os inimigos dentro em {{2}} de dano de Natureza instantaneamente.\n\nOs inimigos na poça sofrem {{3}} de dano de Natureza a cada {{4}} s, e têm uma redução do {{5}}% em velocidade de movimento."}
D[3793]={"^Launches bolts of poison at all enemies within (.-)yd that are standing in the pool created by |cffffffffToxic Sludge|r, dealing (.-) Nature Damage to affected enemies%.%s*$","Dispara rajadas de veneno contra todos os inimigos em um raio de {{1}} m que estejam na poça criada por |cffffffffLodo Tóxico|r, causando {{2}} de dano de Natureza aos alvos atingidos."}
D[3960]={"^|cFF66DDFFLevel 50 Passive|r\nWhen you cast any spell you now have a (.-)%% chance to gain |cffffffffCycle of Decay|r%.%s*$","|cFF66DDFFPassivo de Nível 50|r\nQuando você lança qualquer feitiço agora tem uma chance adicional de {{1}}% de ganhar |cffffffffCiclo de Decomposição|r."}
D[3961]={"^Triggering a |cffffffffVenom|r now has a (.-)%% chance to generate you 5 Energy%.%s*$","Ativar um |cffffffffVeneno|r agora tem {{1}}% de chance de gerar 5 de Energia."}
D[4273]={"^Spew poison on an enemy, dealing (.-) Nature damage and reducing healing received by (.-)%% for (.-), stacking (.-) times%.%s*$","Espiras veneno sobre um inimigo, causando {{1}} de dano de Natureza e reduz a cura recebida em {{2}}% durante {{3}}, acumulando-se {{4}} vezes."}
