D[13395]={"^Finishing move that poisons the target, dealing Nature damage per combo point:\n   1 point: (.-) damage over (.-)%.\n   2 points: (.-) damage over (.-)%.\n   3 points: (.-) damage over (.-)%.\n   4 points: (.-) damage over (.-)%.\n   5 points: (.-) damage over (.-)%.\n\nPeriodic damage from Serpent Venom can critically strike while in Wildcard\n\nThis uses Rip modifiers%.%s*$","Finalizador envenena o alvo, causando dano de Natureza por ponto de combo:\n1 ponto: {{1}} de dano durante {{2}}.\n2 pontos: {{3}} de dano durante {{4}}.\n3 pontos: {{5}} de dano durante {{6}}.\n4 pontos: {{7}} de dano durante {{8}}.\n5 pontos: {{9}} de dano durante {{10}}.\n\nDanos periódicos de Veneno de Serpente podem causar acerto crítico enquanto estiver em Curinga\n\nUsa os modificadores de Rasgar."}
D[13396]={"^Finishing move that poisons the target, dealing Nature damage per combo point:\n   1 point: (.-) damage over (.-)%.\n   2 points: (.-) damage over (.-)%.\n   3 points: (.-) damage over (.-)%.\n   4 points: (.-) damage over (.-)%.\n   5 points: (.-) damage over (.-)%.\n\nThis uses Rip modifiers%.%s*$","Finalizador envenena o alvo, causando dano de Natureza por ponto de combo:\n1 ponto: {{1}} de dano durante {{2}}.\n2 pontos: {{3}} de dano durante {{4}}.\n3 pontos: {{5}} de dano durante {{6}}.\n4 pontos: {{7}} de dano durante {{8}}.\n5 pontos: {{9}} de dano durante {{10}}.\n\nUsa os modificadores de Rasgar."}
D[13399]={"^\nFinishing move that poisons your target%.  Damage increases per combo point and by your attack power and nature power%.%s*$","\nFinalizador que envenena o alvo. O dano aumenta por ponto de combo e com seu poder de ataque e poder de Natureza."}
D[13405]={"^Finishing move that poisons the target, dealing Stormstrike damage per combo point:\n   1 point  : (.-) damage over (.-)\n   2 points: (.-) damage over (.-)\n   3 points: (.-) damage over (.-)\n   4 points: (.-) damage over (.-)\n   5 points: (.-) damage over (.-)%s*$","Finalizador envenena o alvo, causando dano de Golpe da Tempestade por ponto de combo:\n1 ponto: {{1}} de dano durante {{2}}\n2 pontos: {{3}} de dano durante {{4}}\n3 pontos: {{5}} de dano durante {{6}}\n4 pontos: {{7}} de dano durante {{8}}\n5 pontos: {{9}} de dano durante {{10}}."}
D[13406]={"^Finishing move that poisons the target, dealing Stormstrike damage per combo point:\n   1 point  : (.-) damage over (.-)\n   2 points: (.-) damage over (.-)\n   3 points: (.-) damage over (.-)\n   4 points: (.-) damage over (.-)\n   5 points: (.-) damage over (.-)\n   \nThis uses Rip modifiers%.%s*$","Finalizador envenena o alvo, causando dano de Golpe da Tempestade por ponto de combo:\n1 ponto: {{1}} de dano durante {{2}}\n2 pontos: {{3}} de dano durante {{4}}\n3 pontos: {{5}} de dano durante {{6}}\n4 pontos: {{7}} de dano durante {{8}}\n5 pontos: {{9}} de dano durante {{10}}\n\nUsa os modificadores de Rasgar."}
D[13647]={"^\nStrike the target causing them to take poison damage for (.-) damage plus an additional (.-) %(based on weapon damage%) over (.-)%.%s*$","\nAtinge o alvo, causando {{1}} de dano de Veneno mais {{2}} (com base no dano da arma) ao longo de {{3}}."}
D[13682]={"^Deals Nature damage every (.-) seconds for (.-)%. If this reaches 3 stacks or the target dies, Cobra Venom is Expunged, dealing (.-) Nature damage to enemies within 10 yards%.%s*$","Causa dano de Natureza a cada {{1}} segundos durante {{2}}. Se isto alcança 3 acúmulos ou o alvo morre, Veneno de Cobra é Expurgado, causando {{3}} de dano de Natureza aos inimigos dentro de 10 metros."}
D[13776]={"^Increases the damage of the casters Instant Poison and Deadly Poison by (.-)%%%. Stacks (.-) times%. Lasts for 12 seconds%.%s*$","Aumenta o dano do Veneno Instantâneo e do Veneno Mortal do conjurador em {{1}}%. Acumula {{2}} vezes. Dura 12 segundos."}
D[13883]={"^Strike the target, inflicting a poisoned bleed that deals (.-) Nature damage and an additional (.-) %(based on weapon damage%) over (.-)%.\n\nThis ability is usable while shapeshifted%.%s*$","Golpeia o alvo, causando uma hemorragia venenosa que causa {{1}} de dano de Natureza e um adicional de {{2}} (baseado no dano da arma) durante {{3}}.\n\nEsta habilidade pode ser usada enquanto você estiver transformado."}
D[13884]={"^Strike the target, inflicting a poisoned bleed that deals (.-) Nature damage and an additional (.-) %(based on weapon damage%) over (.-)%.\n\nThis ability is usable while shapeshifted%.\n\nThis uses Rend modifiers and counts as both a bleed and poison effect%.%s*$","Golpeia o alvo, causando uma hemorragia venenosa que causa {{1}} de dano de Natureza e um adicional de {{2}} (baseado no dano da arma) durante {{3}}.\n\nEsta habilidade pode ser usada enquanto você estiver transformado.\n\nEste usa os modificadores de Rasgar e conta como efeito tanto de hemorragia como venenoso."}
D[13898]={"^Your next Ravage can be cast outside of Prowl, has no positional requirement, and costs (.-) less energy and deals (.-)%% increased damage against monsters, and reduces the cooldown of Shadow Dance by (.-) sec%.%s*$","Seu próximo Devastar pode ser usado fora de Espreitar, não exige posição específica, custa {{1}} a menos de Energia, causa {{2}}% a mais de dano contra monstros e reduz em {{3}} s a recarga de Dança das Sombras."}
D[13899]={"^Your next Ravage can be cast outside of Prowl, has no positional requirement, and costs (.-) less energy and deals (.-)%% increased damage against monsters, and reduces the cooldown of Shadow Dance by (.-) sec%.\n\nDeals (.-)%% less damage against players%s*$","Seu próximo Devastar pode ser usado fora de Espreitar, não exige posição específica, custa {{1}} a menos de Energia, causa {{2}}% a mais de dano contra monstros e reduz em {{3}} s a recarga de Dança das Sombras.\n\nCausa {{4}}% a menos de dano contra jogadores."}
D[13900]={"^Dealing damage with Rake or Rip has a (.-)%% chance and Shred has a (.-)%% chance to grant you |cFFFFFFFFAmbush Predator|r%.%s*$","Causar dano com Ancinho ou Rasgar tem {{1}}% de chance, e Destroçar tem {{2}}% de chance, de conceder |cFFFFFFFFPredador de Emboscada|r."}
D[13901]={"^Your Shred casts are guaranteed to, and your bleed ticks have a chance to make your next Ravage useable outside of Stealth and decrease it's energy cost%.%s*$","Usar |cffffffffRetalhar|r garante que seu próximo |cffffffffDevastar|r possa ser usado fora da Furtividade e tenha o custo de Energia reduzido. Os pulsos dos seus efeitos de Sangramento também têm uma chance de conceder esse efeito."}
D[13902]={"^Your next Ravage does not require stealth, has no positional requirement and costs (.-) less energy, and reduces the cooldown of Shadow Dance by (.-) sec%. Lasts (.-)%.%s*$","Seu próximo Devastar não requer Furtividade nem posição específica, custa {{1}} a menos de Energia e reduz em {{2}} s a recarga de Dança das Sombras. Dura {{3}}."}
