D[79576]={"^Your Bloodthirst applies Blood Venom, dealing Nature damage over time and increasing the damage taken by your Rogue Poisons by 30%% per stack%. This effect stacks up to 3 times%.\n\nDealing damage with Rend, Garrote or Rupture applies a stack Internal Bleeding to the target, increasing the damage of your Hemorrhage by 5%%%. This effect stacks up to 20 times%.\n\nThis does not work while in Cat or Bear Form%.%s*$","Sua |cffffffffSede de Sangue|r aplica |cffffffffVeneno de Sangue|r, causando dano de Natureza ao longo do tempo e aumentando em 30% por acúmulo o dano que o alvo recebe dos seus Venenos de Ladino. Acumula até 3 vezes.\n\nCausar dano com |cffffffffDilacerar|r, Garrote ou |cffffffffRuptura|r aplica Sangramento Interno ao alvo, aumentando em 5% por acúmulo o dano de |cffffffffHemorragia|r. Acumula até 20 vezes.\n\nNão funciona em Forma de Felino nem Forma de Urso."}
D[80427]={"^Healing a target with a direct heal below 50%% health grants you Power Word: Celerity, which grants you (.-) spell haste rating for (.-)%. This effect cannot occur more than once every 15 sec%.%s*$","Cura um alvo com um feitiço direto quando está abaixo de 50% de vida concede a você Palavra de Potencializa: Celeridade, que concede a você {{1}} índice de Celeridade com feitiços durante {{2}}. Este efeito não pode acontecer mais de uma vez a cada 15 s."}
D[81016]={"^Your Bloodthirst increases the damage dealt by Deadly Poison by (.-)%%, and Rupture by (.-)%%%. Stacks up to (.-)%.\n\nDeadly Poison increases the damage taken from the caster's combo point generating abilities by (.-)%%%. Stacks up to (.-)%.\n\nDealing damage with Rend, Garrote or Rupture grants you a stack of |cFFFFFFFFBloody Strikes|r%.%s*$","Sua |cffffffffSede de Sangue|r aumenta em {{1}}% o dano de |cffffffffVeneno Mortal|r e em {{2}}% o dano de |cffffffffRuptura|r. Acumula até {{3}} vezes.\n\n|cffffffffVeneno Mortal|r aumenta em {{4}}% o dano recebido das habilidades do conjurador que geram pontos de combo. Acumula até {{5}} vezes.\n\nCausar dano com |cffffffffDilacerar|r, Garrote ou |cffffffffRuptura|r concede um acúmulo de |cFFFFFFFFGolpes Sangrentos|r."}
D[81056]={"^Blood Venom Bloodthirst Proc SLS%s*$","Proc Sangue de Veneno SLS."}
D[81057]={"^Deals (.-) Nature damage every 3 seconds%.%s*$","causa {{1}} de dano de Natureza a cada 3 segundos."}
D[81135]={"^Blood Venom Bloody Strikes Warrior Proc SLS%s*$","Golpes sanguentos Sangue venenosa Guerreiro Ativação SLS."}
D[81136]={"^Blood Venom Bloody Strikes Rogue Proc SLS%s*$","Veneno de Sangue — Golpes Sangrentos — Ladino — Proc SLS"}
D[81313]={"^Blood Venom Toxic Strikes Proc SLS%s*$","Golpes Tóxicos com Sangueveneno SLS."}
D[81316]={"^Blood Venom Bloothirst 3 stack SLS%s*$","SLS de 3 acúmulos de Sede de Sangue do Veneno de Sangue."}
D[82882]={"^Consuming 10 stacks of |cFFFFFFFFToxic Strikes|r now applies |cFFFFFFFFBlood Venom|r to your target%.%s*$","Consumindo 10 acúmulos de |cFFFFFFFFGolpes Tóxicos|r agora aplica |cFFFFFFFFVeneno de Sangue|r ao alvo."}
D[83431]={"^\nTransforms your Black Arrow into Black Widow Strike%.\n\nThis ability scales from your Black Arrow modifiers%.%s*$","\nTransforma sua Flecha Negra em |cFFFFFFFFGolpe da Viúva-Negra|r.\n\nEsta habilidade escala com os mesmos modificadores da Flecha Negra."}
