D[85440]={"^Does (.-) nature damage to the target over (.-)%.%s*$","causa {{1}} de dano de Natureza ao alvo durante {{2}}."}
D[85489]={"^Inflicts (.-) Nature damage to an enemy, then an additional (.-) damage every (.-) sec%. for (.-)%.%s*$","Causa {{1}} de dano de Natureza a um inimigo e depois dano adicional de {{2}} a cada {{3}} s durante {{4}}."}
D[85614]={"^Inflicts (.-) Nature damage to an enemy every (.-) sec%. for (.-)%.%s*$","Causa {{1}} de dano de Natureza a um inimigo a cada {{2}} s durante {{3}}."}
D[85628]={"^Inflicts (.-) Nature damage to an enemy every (.-) sec%., increasing the time between its attacks by (.-)%% and slowing its movement by (.-)%% for (.-)%.%s*$","Causa {{1}} de dano de Natureza a um inimigo a cada {{2}} s, aumenta o tempo entre seus ataques {{3}}% e reduz seu movimento {{4}}% durante {{5}}."}
D[85646]={"^Spits poison at an enemy, inflicting Nature damage, then additional damage every (.-) sec%. for (.-)%.%s*$","Cospe veneno no inimigo e causa dano de Natureza e dano adicional a cada {{1}} s durante {{2}}."}
D[85753]={"^Increases spell power by (.-)%.%s*$","Aumenta o poder mágico em {{1}}."}
D[85804]={"^Target is cured of poisons up to level 25%.%s*$","O alvo se cura de envenenamentos até o nível 25."}
D[85805]={"^Target is cured of poisons up to level 35%.%s*$","O alvo se cura de envenenamentos até o nível 35."}
D[85806]={"^Creates 3 Vials of Anti%-Venom%.%s*$","Cria 3 frascos de contraveneno."}
D[85807]={"^Creates 3 Vials of Strong Anti%-Venom%.%s*$","Cria 3 frascos de contraveneno forte."}
D[85810]={"^Inflicts Nature damage to an enemy%.%s*$","Causa dano de Natureza a um inimigo."}
D[86336]={"^Poisons all enemies in an (.-) yard radius around the caster%.  Victims of the poison suffer (.-) Nature damage every 5 sec for 45 sec%.%s*$","Envenena todos os inimigos em um raio de {{1}} m ao redor do conjurador. As vítimas do envenenamento sofrem {{2}} de dano de Natureza a cada 5 s durante 45 s."}
D[86504]={"^Increases the Physical damage taken by nearby enemies by (.-)%% for (.-)%.%s*$","aumenta em {{1}}% o dano Físico causado os inimigos próximos durante {{2}}."}
D[86746]={"^Cures (.-) poison (.-)%.%s*$","Cura {{1}} {{2}} de envenenamento."}
D[86747]={"^Spits poison at an enemy, causing harm and inflicting additional Nature damage every (.-) sec%. for (.-)%.%s*$","Cospe veneno em um inimigo e causa dano e dano adicional de Natureza a cada {{1}} s durante {{2}}."}
D[86807]={"^Spits poison at nearby enemies, inflicting Nature damage, then additional damage every (.-) sec%. for (.-)%.%s*$","Cospe veneno nos inimigos próximos e causa dano de Natureza e dano adicional a cada {{1}} s durante {{2}}."}
D[86973]={"^Damage dealt is decreased by (.-)%%%.%s*$","Dano causado reduzido em {{1}}%."}
D[87377]={"^Spits poison at an enemy, inflicting harm, reducing the target's armor, and causing additional Nature damage every (.-) sec%. for (.-)%.%s*$","Cospe veneno no inimigo e causa dano, reduzindo sua armadura e causa dano adicional de Natureza a cada {{1}} s durante {{2}}."}
D[87439]={"^Shoots poison at an enemy, inflicting Nature damage, then additional damage every (.-) sec%. for (.-)%.%s*$","Dispara veneno no inimigo e causa dano de Natureza e dano adicional a cada {{1}} s durante {{2}}."}
