D[88139]={"^Deals (.-) Nature damage every (.-) sec to targets within (.-) yards, reducing their movement speed for (.-)%.%s*$","Causa {{1}} de dano de Natureza a cada {{2}} s aos alvos em um raio de {{3}} m, reduz sua velocidade de movimento durante {{4}}."}
D[88173]={"^Spikes sprout from you causing (.-) Nature damage to attackers when hit%.  Lasts (.-)%.%s*$","Espinhos brotam de você, causando {{1}} de dano de Natureza aos atacantes quando você é atingido. Dura {{2}}."}
D[88223]={"^Inflicts Nature damage to nearby enemies for (.-)%.%s*$","Causa dano de Natureza aos inimigos próximos durante {{1}}."}
D[88400]={"^Spits poison at an enemy, inflicting Nature damage%.%s*$","Cospe veneno no inimigo e causa dano de Natureza."}
D[88453]={"^A poison cloud appears which grows in area over (.-)%.%s*$","Uma nuvem de veneno aparecem e cresce na zona durante {{1}}."}
D[88556]={"^A web tightly wraps around the target, stunning and dealing (.-) Nature damage every (.-) sec%. until the web wrap is destroyed%.%s*$","O alvo queda envolto em uma teia que lhe atordoa e causa {{1}} de dano de Natureza a cada {{2}} s até que se destrói a armadilha aracnídea."}
D[88756]={"^Chance to strike your ranged target with a Venom Shot for (.-) Nature damage%.%s*$","Chance de atingir seu alvo à distância com um Disparo venenoso, causa {{1}} de dano de Natureza."}
D[88765]={"^Venom Shot for (.-) Nature damage%.%s*$","Disparo venenoso que causa {{1}} de dano de Natureza."}
D[88997]={"^Creates a poison cloud beneath Broggok%.%s*$","Cria uma nuvem de veneno debaixo de Broggok."}
D[89243]={"^Removes (.-) poison (.-)%.  Lowers Nature Resistance by (.-) for (.-)%.%s*$","Remove {{1}} {{2}} de veneno. Reduz a resistência à Natureza {{3}} durante {{4}}."}
D[90096]={"^Shoots poison at an enemy, inflicting Nature damage%.%s*$","Dispara veneno no inimigo e causa dano de Natureza."}
D[90237]={"^Creates a gaseous cloud to poison Human Pieces in the area of effect for (.-) Nature damage over (.-)%.%s*$","Cria uma nuvem de gás para envenenar às peças humanas que se encontrem na zona defeito causando {{1}} de dano de Natureza durante {{2}}."}
D[91223]={"^Spits poison at an enemy, inflicting (.-) Nature damage, then additional (.-) damage every (.-) sec%. for (.-)%.%s*$","Cospe veneno no inimigo e causa {{1}} de dano de Natureza e {{2}} de dano adicional a cada {{3}} s durante {{4}}."}
D[91602]={"^Deals (.-) Nature damage and increases Physical damage taken by (.-)%%%.%s*$","Causa {{1}} de dano de Natureza e aumenta o dano Físico recebide {{2}}%."}
D[92845]={"^Channels a beam of webbing, rendering the target unable to move for (.-)%. When the effect ends, the target will be encased in webs, stunning them for (.-)%. If the webs surrounding the targets are killed, the target will be released%.%s*$","Canaliza um feixe de teia que impede que o alvo se mudar durante {{1}}. Quando o efeito se acaba, o alvo se reviste de teias e queda atordoado durante {{2}}. Se matam as teias que cercam o alvo, este se liberará."}
D[93404]={"^Channels a beam of webbing, rendering the target unable to move and inflicting (.-) Shadow damage after (.-) sec%.%s*$","Canaliza um feixe de teia que imobiliza o alvo e causa {{1}} de dano de Sombra após {{2}} s."}
D[96173]={"^Applies a paralytic toxin that inflicts increasing Nature damage every (.-) sec%. and reduces movement speed over time until the victim is entirely paralyzed%. Exposure to Burning Bile neutralizes Paralytic Toxin%.%s*$","Aplica uma Toxina paralisante que causa dano de Natureza em aumento a cada {{1}} s e reduz a velocidade de movimento no tempo até que a vítima queda completamente paralisada. A exposição a Bile ardente neutraliza a Toxina paralisante."}
D[96665]={"^Damage taken reduced by (.-)%%%.%s*$","O dano recebido é reduzido em {{1}}%."}
D[96691]={"^Whenever the caster lands a melee swing, the target takes (.-) Nature damage every (.-) seconds and their armor is reduced by (.-)%%%. This effect can stack up to 5 times%. Lasts (.-)%.%s*$","Sempre que o conjurador impacte com um golpe corpo a corpo, o alvo recebe {{1}} de dano de Natureza a cada {{2}} segundos e sua armadura é reduzida em {{3}}%. Este efeito se pode acumular até 5 vezes. Dura {{4}}."}
D[98120]={"^Sprays toxic webs at the target, preventing movement for (.-) and causing Nature damage over time%.%s*$","Rega o alvo com teias tóxicas, impedindo seu movimento durante {{1}} e causando dano de Natureza ao longo do tempo."}
