T[20115]={"^Blood Venom Bloodthirst Proc SLS%s*$","Proc Sangue de Veneno SLS."}
T[20116]={"^Deals (.-) Nature damage every 3 seconds%.%s*$","causa {{1}} de dano de Natureza a cada 3 segundos."}
T[20177]={"^Blood Venom Bloody Strikes Warrior Proc SLS%s*$","Golpes sanguentos Sangue venenosa Guerreiro Ativação SLS."}
T[20178]={"^Blood Venom Bloody Strikes Rogue Proc SLS%s*$","Veneno de Sangue — Golpes Sangrentos — Ladino — Proc SLS"}
T[20242]={"^Blood Venom Toxic Strikes Proc SLS%s*$","Golpes Tóxicos com Sangueveneno SLS."}
T[20245]={"^Blood Venom Bloothirst 3 stack SLS%s*$","SLS de 3 acúmulos de Sede de Sangue do Veneno de Sangue."}
T[20554]={"^Causes Nature damage to the target, duplicated to other targets affected by your Rupture or Crimson Tempest%.%s*$","causa dano de Natureza ao alvo, duplicado para outros alvos afetados por Seu Ruptura ou Tempestade Carmesim."}
T[20844]={"^The venom starts off strong, dealing (.-) damage every second%.\n\nHas a 33%% chance to resist dispels%.%s*$","O veneno começa forte, causando {{1}} de dano a cada segundo.\n\ntem chance de 33% para resistir as desintoxicações."}
T[20845]={"^The spreading venom grows less potent the more it spreads from its origin, dealing (.-) damage every two seconds%.\n\nHas a 10%% chance to resist Dispels%.%s*$","À medida que o veneno se propaga a partir da origem, vai perdendo potência e causa {{1}} de dano cada dois segundos.\n\ntem 10% de chance de resistir a efeitos de remoção de veneno."}
T[20881]={"^The skin and flesh of the cultist begins to bubble and boil%. It's begins to morph and bend, but it seems to not exceed a certain threshold, perhaps it needs some kind of catalyst%. You may not want to allow the Grand Widow to give them just that%.%s*$","A pele e a carne do cultista começam a borbulhar e ferver. O corpo começa a se transformar e retorcer, mas parece não ultrapassar certo limite; talvez precise de algum catalisador. É melhor não permitir que a Grande Viúva forneça exatamente isso."}
T[21497]={"^The ground is seeping with Harbinger Varikesh's paralytic toxin, reducing movement speed by (.-)%%%.%s*$","O solo está impregnado pela toxina paralisante do Arauto Varikesh, reduzindo a velocidade de movimento em {{1}}%."}
T[21584]={"^Blood Venom Venomous Wound SLS%s*$","SLS de Ferida Venenosa do Veneno de Sangue."}
T[21585]={"^Blood Venom Bloodthirst Poison Proc%s*$","Veneno de Sangue, Fome de Sangue, Proc de Veneno."}
